using System.Diagnostics.CodeAnalysis;
using System.Reflection;
using System.Text.Json;
namespace Axiom.Gameplay;
internal static class ScriptValues {
 private static FieldInfo? Field(Type type,string name){for(Type? current=type;current!=null;current=current.BaseType){var field=current.GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly);if(field!=null)return field;}return null;}
 internal static void ValidateClone(Type type,Script source)=>CloneSerialization.Validate(type,source);
 internal static void RemapClone(Type type,Script clone,Dictionary<string,Entity> entities)=>CloneSerialization.Remap(type,clone,entities);
 internal static void Copy(Type type,Script source,Script target)=>CloneSerialization.Copy(type,source,target);
 internal static void Apply([DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicFields|DynamicallyAccessedMemberTypes.NonPublicFields)] Type type,object script,JsonElement values){
  if(values.ValueKind!=JsonValueKind.Object)throw new ArgumentException("Script fields must be an object");
  foreach(var property in values.EnumerateObject()){var field=Field(type,property.Name);if(field==null||field.IsInitOnly||field.IsStatic||field.GetCustomAttribute<HideInInspectorAttribute>()!=null||!field.IsPublic&&field.GetCustomAttribute<SerializeFieldAttribute>()==null)continue;field.SetValue(script,Read(field.FieldType,property.Value));}
 }
 internal static void Write([DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicFields|DynamicallyAccessedMemberTypes.NonPublicFields)] Type type,object script,Utf8JsonWriter writer,string[] names){writer.WriteStartObject();foreach(var name in names){var f=Field(type,name);if(f==null)continue;writer.WritePropertyName(name);var v=f.GetValue(script);switch(v){case bool x:writer.WriteBooleanValue(x);break;case string x:writer.WriteStringValue(x);break;case Enum x:writer.WriteNumberValue(Convert.ToInt32(x));break;case byte x:writer.WriteNumberValue(x);break;case short x:writer.WriteNumberValue(x);break;case int x:writer.WriteNumberValue(x);break;case uint x:writer.WriteNumberValue(x);break;case long x:writer.WriteNumberValue(x);break;case float x:writer.WriteNumberValue(x);break;case double x:writer.WriteNumberValue(x);break;
case UnityEngine.Object ux: {if(!ux.Native){writer.WriteNullValue();break;}writer.WriteStartObject();if(RuntimeAssets.IsAsset(ux.Native))writer.WriteString("path",RuntimeAssets.Reference(ux.Native));else if(ux.Native is GameObject go)writer.WriteString("entityId",go.Entity.Id);else if(ux.Native is Component component){writer.WriteString("entityId",component.Entity.Id);writer.WriteString("component",ScriptBridge.ComponentType(component).Name);if(component is Script scriptReference)writer.WriteString("path",RuntimeLifecycle.PathOf(scriptReference));}else if(ux.Native is ProjectAsset asset)writer.WriteString("path",asset.Path);else if(ux.Native is TextAsset textAsset)writer.WriteString("path",textAsset.Path);else if(ux.Native is PrefabAsset prefab)writer.WriteString("path",prefab.Path);else if(ux.Native is SceneAsset scene)writer.WriteString("path",scene.Path);writer.WriteEndObject();break;
} case Object x: {if(!x){writer.WriteNullValue();break;}writer.WriteStartObject();if(RuntimeAssets.IsAsset(x))writer.WriteString("path",RuntimeAssets.Reference(x));else if(x is GameObject go)writer.WriteString("entityId",go.Entity.Id);else if(x is Component component){writer.WriteString("entityId",component.Entity.Id);writer.WriteString("component",ScriptBridge.ComponentType(component).Name);if(component is Script scriptReference)writer.WriteString("path",RuntimeLifecycle.PathOf(scriptReference));}else if(x is ProjectAsset asset)writer.WriteString("path",asset.Path);else if(x is TextAsset textAsset)writer.WriteString("path",textAsset.Path);else if(x is PrefabAsset prefab)writer.WriteString("path",prefab.Path);else if(x is SceneAsset scene)writer.WriteString("path",scene.Path);writer.WriteEndObject();break;
} case Vector2 x: Numbers(writer,x.X,x.Y);break;
case Vector3 x: Numbers(writer,x.X,x.Y,x.Z);break;case UnityEngine.Vector3 x: Numbers(writer,x.x,x.y,x.z);break;case UnityEngine.Quaternion x: Numbers(writer,x.x,x.y,x.z,x.w);break;
case Vector4 x: Numbers(writer,x.X,x.Y,x.Z,x.W);break;
case Vector2Int x: Numbers(writer,x.X,x.Y);break;
case Vector3Int x: Numbers(writer,x.X,x.Y,x.Z);break;
case Vector4Int x: Numbers(writer,x.X,x.Y,x.Z,x.W);break;
case Vec3 x: Numbers(writer,x.X,x.Y,x.Z);break;
case Quat x: Numbers(writer,x.X,x.Y,x.Z,x.W);break;
case Quaternion x: Numbers(writer,x.X,x.Y,x.Z,x.W);break;
case Color x: Numbers(writer,x.R,x.G,x.B,x.A);break;
case Color32 x: Numbers(writer,x.R,x.G,x.B,x.A);break;
case Rect x: Numbers(writer,x.X,x.Y,x.Width,x.Height);break;
case Bounds x: Numbers(writer,x.Center.X,x.Center.Y,x.Center.Z,x.Size.X,x.Size.Y,x.Size.Z);break;
 case null:if(typeof(Object).IsAssignableFrom(f.FieldType)||typeof(UnityEngine.Object).IsAssignableFrom(f.FieldType))writer.WriteNullValue();else writer.WriteStringValue("");break;default:writer.WriteNullValue();break;}}writer.WriteEndObject();}
 private static void Numbers(Utf8JsonWriter writer,params double[] values){writer.WriteStartArray();foreach(var v in values)writer.WriteNumberValue(v);writer.WriteEndArray();}
 private static object? Read(Type type,JsonElement e){
if(typeof(UnityEngine.Object).IsAssignableFrom(type)){if(e.ValueKind==JsonValueKind.Null)return null;if(e.TryGetProperty("path",out var assetPath)&&!e.TryGetProperty("entityId",out _)){var resolved=RuntimeAssets.Resolve(assetPath.GetString()!);if(resolved==null){var nativeType=type==typeof(UnityEngine.Mesh)?typeof(Mesh):type==typeof(UnityEngine.TextAsset)?typeof(TextAsset):type==typeof(UnityEngine.Texture2D)?typeof(Texture2D):type==typeof(UnityEngine.AudioClip)?typeof(AudioClip):typeof(Object);resolved=Read(nativeType,e) as Object;}return resolved!=null&&type.IsInstanceOfType(UnityEngine.Object.Wrap(resolved))?UnityEngine.Object.Wrap(resolved):null;}var id=e.GetProperty("entityId").GetString()!;if(!Context.Entities.ContainsKey(id))return null;var go=new GameObject(new Entity(id,Context.Generation));if(type==typeof(UnityEngine.GameObject)||type==typeof(UnityEngine.Object)&&!e.TryGetProperty("component",out _)&&!e.TryGetProperty("path",out _))return UnityEngine.Object.Wrap(go);var path=e.TryGetProperty("path",out var file)?file.GetString():null;var found=go.AllComponents().FirstOrDefault(c=>ScriptBridge.Matches(type,c)&&(path==null||c is Script script&&RuntimeLifecycle.PathOf(script)==path));return found==null?null:UnityEngine.Object.Wrap(found);}
  if(typeof(Object).IsAssignableFrom(type)){if(e.ValueKind==JsonValueKind.Null)return null;if(type==typeof(GameObject)||typeof(Component).IsAssignableFrom(type)){var id=e.GetProperty("entityId").GetString()!;if(!Context.Entities.ContainsKey(id))return null;var entity=new Entity(id,Context.Generation);if(type==typeof(GameObject))return new GameObject(entity);var path=e.TryGetProperty("path",out var file)?file.GetString():null;return new GameObject(entity).GetComponents<Component>().FirstOrDefault(c=>type.IsInstanceOfType(c)&&(path==null||c is Script s&&RuntimeLifecycle.PathOf(s)==path));}var source=e.GetProperty("path").GetString()!;if(source.StartsWith(RuntimeAssets.Prefix,StringComparison.Ordinal)){var asset=RuntimeAssets.Resolve(source);return asset!=null&&type.IsInstanceOfType(asset)?asset:null;}if(type==typeof(TextAsset))return Resources.Load<TextAsset>(source);if(type==typeof(SceneAsset))return Resources.Load<SceneAsset>(source);if(type==typeof(PrefabAsset))return Resources.Load<PrefabAsset>(source);if(type==typeof(Texture2D))return Resources.Load<Texture2D>(source);if(type==typeof(AudioClip))return Resources.Load<AudioClip>(source);if(type==typeof(Mesh))return Resources.Load<Mesh>(source);throw new NotSupportedException("Unsupported asset reference "+type.Name);}

  if(type==typeof(bool))return e.GetBoolean();if(type==typeof(string))return e.GetString()??"";
  if(type.IsEnum)return Enum.ToObject(type,e.GetInt32());if(type==typeof(int))return e.GetInt32();if(type==typeof(uint))return e.GetUInt32();if(type==typeof(short))return e.GetInt16();if(type==typeof(byte))return e.GetByte();if(type==typeof(long))return e.GetInt64();if(type==typeof(float))return (float)e.GetDouble();if(type==typeof(double))return e.GetDouble();
  if(type==typeof(UnityEngine.Vector3))return (UnityEngine.Vector3)Vector3.Read(e);if(type==typeof(UnityEngine.Quaternion))return (UnityEngine.Quaternion)Quaternion.Read(e);if(type==typeof(Vector2))return Vector2.Read(e);if(type==typeof(Vector3))return Vector3.Read(e);if(type==typeof(Vector4))return Vector4.Read(e);if(type==typeof(Vector2Int))return Vector2Int.Read(e);if(type==typeof(Vector3Int))return Vector3Int.Read(e);if(type==typeof(Vector4Int))return Vector4Int.Read(e);if(type==typeof(Vec3))return Vec3.Read(e);if(type==typeof(Quat))return Quat.Read(e);if(type==typeof(Quaternion))return Quaternion.Read(e);if(type==typeof(Color))return new Color(e[0].GetDouble(),e[1].GetDouble(),e[2].GetDouble(),e[3].GetDouble());if(type==typeof(Rect))return new Rect(e[0].GetDouble(),e[1].GetDouble(),e[2].GetDouble(),e[3].GetDouble());if(type==typeof(Bounds))return new Bounds(new Vector3(e[0].GetDouble(),e[1].GetDouble(),e[2].GetDouble()),new Vector3(e[3].GetDouble(),e[4].GetDouble(),e[5].GetDouble()));if(type==typeof(Color32))return new Color32(e[0].GetByte(),e[1].GetByte(),e[2].GetByte(),e[3].GetByte());throw new ArgumentException("Unsupported serialized field type");
 }
}
